int factorial(int n)
{
    int totalValueSoFar = 1;
    int baseCaseReached = 0;
    int i = 0;
    i = i + 1;
    if (n == 0)
    {
        totalValueSoFar = 1;
        baseCaseReached = 1;
    }
    else
    {
        totalValueSoFar = n * factorial(n);
        baseCaseReached = 0;
    }
    return totalValueSoFar;
}
